from questions._util import IX, q

LAN = "https://labs.iximiuz.com/courses/computer-networking-fundamentals/from-lan-to-vxlan"
BRIDGE = "https://labs.iximiuz.com/courses/computer-networking-fundamentals/bridge-vs-switch"
DUAL = "https://labs.iximiuz.com/challenges/networking-block-unexpected-access-on-dual-homed-server"
SSH = "https://labs.iximiuz.com/skill-paths/master-ssh-tunnels"

QUESTIONS = [
    q("net-osi", "medium", "A colleague says the office LAN is one IP subnet. What did the networking course actually say a LAN is?", "A LAN is defined by locality. It can contain several IP networks joined by routers.", "A LAN is exactly one /24.", "A LAN is any traffic that uses TCP.", "A LAN cannot contain a router.", "Proximity defines the LAN, not the L3 topology. One building can hold many subnets.", IX, LAN),
    q("net-osi", "medium", "Two hosts in one broadcast domain can exchange frames without a router. Which layer is that?", "Layer 2. A router is what joins separate L3 networks.", "Layer 4. Broadcast domains are TCP connections.", "Layer 7.", "Layer 1 only. MAC addresses are not used.", "Bridges and switches forward frames inside an L2 segment. Routing starts when the IP networks differ.", IX, BRIDGE),
    q("net-osi", "easy", "What does a transparent bridge do from the host's point of view?", "Nothing visible. Hosts send frames, and the bridge learns which MAC is behind which port.", "It rewrites every IP address.", "It terminates TLS.", "It requires each host to configure the bridge as a default gateway.", "Transparency means the endpoints do not address the bridge. They address each other.", IX, BRIDGE),
    q("net-osi", "hard", "Why do operators avoid one giant L2 domain across a data center?", "A huge broadcast domain is brittle. A loop or a storm takes a lot of machines with it.", "L2 cannot carry IP, so a large domain cannot route.", "Broadcasts are unicast and therefore free.", "Switches drop every broadcast, so size does not matter.", "The practical design is smaller L2 segments joined by L3, which is what a top-of-rack switch is doing for the rack.", IX, BRIDGE),
    q("net-ip", "medium", "10.0.0.0/8 and 10.1.0.0/16. Does the second sit inside the first?", "Yes. /16 is a longer prefix inside /8.", "No. Different prefix lengths can never nest.", "Only if both are public.", "Only on IPv6.", "A longer prefix is a subset when the bits match. 10.1.0.0/16 is inside 10.0.0.0/8."),
    q("net-ip", "medium", "A host is 10.1.4.20/24. Which address is the typical subnet broadcast, and who hears it?", "10.1.4.255, and only hosts in 10.1.4.0/24.", "10.1.255.255, because the second octet decides.", "255.255.255.255, and the whole internet.", "10.1.4.0, which is the usual host address.", "For a /24 the last address of the range is the directed broadcast. The network address is the bottom of the range, not a host you should use."),
    q("net-ip", "hard", "Two hosts have addresses in the same subnet on the diagram, but a ping says no route to host. What is still possible?", "They are not actually on a shared L2 segment, or one of them has the wrong mask and never ARPs.", "IP never needs ARP.", "Ping does not use the routing table.", "Same subnet always means the packets leave via the default gateway.", "Same numbers on a slide are not a cable. Check the mask, the neighbor table, and whether a VLAN split them."),
    q("net-ip", "easy", "What is the point of a private range such as 10.0.0.0/8?", "It is not routed on the public internet. You can reuse it inside networks you control.", "It is faster than a public address.", "It cannot be NATed.", "IANA assigns one 10/8 per company.", "Private addresses need NAT or a tunnel to reach the public internet. They are not secret by themselves."),
    q("net-routing", "medium", "A host has a default route and a more specific route to 10.20.0.0/24. A packet to 10.20.0.10 uses which?", "The more specific route. Longest prefix wins.", "The default route, because it is listed first in the textbook.", "Whichever interface is eth0.", "Both, and the kernel picks at random.", "Specific beats general. That is how a VPN route overrides the default for an internal range."),
    q("net-routing", "medium", "ip route get 1.1.1.1 is useful because:", "It shows the route the kernel would use for that destination, including the device and gateway.", "It sends a traceroute.", "It edits the default route.", "It prints only IPv6.", "Ask the kernel what it would do before you assume the table matches the diagram."),
    q("net-routing", "hard", "A packet arrives on eth0 destined to an address that lives on eth1 of the same host. The service is bound to the eth1 address. What does a weak end host do?", "It accepts the packet. Local delivery does not require the arrival interface to own that address.", "It drops the packet as a routing error.", "It forwards it back out eth0.", "It rewrites the destination to eth0's address.", "Binding to one address does not stop another interface from delivering that address. Filter on the ingress interface if the split matters.", IX, DUAL),
    q("net-routing", "easy", "What does a default route mean?", "Where to send packets that match nothing more specific.", "The route used for packets to the host itself.", "A route that always wins.", "The MAC table.", "0.0.0.0/0 or ::/0 is the catch-all. Without it, only connected and explicit routes work."),
    q("net-dns", "medium", "A pod resolves some short names and not others. ndots is 5. What is going on?", "A name with fewer than 5 dots is tried against every search domain first, which multiplies queries and can hit the wrong suffix.", "ndots disables DNS.", "Short names skip search domains.", "ndots is a TLS setting.", "cluster.local search plus a high ndots is why a typo becomes several slow lookups. Absolute names with a trailing dot skip the search list."),
    q("net-dns", "medium", "dig +trace and dig @ns both exist. What is the difference you care about when a record looks wrong?", "+trace walks from the root. Querying a specific server shows what that server says, which may be a cache or a different view.", "They always print the same answer.", "+trace edits the zone.", "@ns sends email.", "Decide whether the bug is delegation, the authoritative server, or a recursive cache in the middle."),
    q("net-dns", "hard", "You changed a record and some clients still see the old value. What is the usual reason?", "TTL. Resolvers are allowed to keep the previous answer until it expires.", "DNS never caches.", "UDP cannot carry a new record on the same day.", "The zone serial is decorative and unused.", "Lower the TTL before the change if you need a fast cut. After the change, wait out the old TTL."),
    q("net-dns", "easy", "What does /etc/resolv.conf nameserver mean?", "The recursive resolver this host will ask. It is not the list of every authoritative server on the internet.", "The host's own zone.", "A static ARP entry.", "The default route.", "Get that resolver wrong and every name fails while IP addresses still work."),
    q("net-tcp", "medium", "A connection is stuck in SYN_SENT. What did not happen?", "The handshake did not complete. You sent a SYN and did not get a SYN-ACK you accepted.", "The application finished the HTTP response.", "The socket is in TIME_WAIT after a clean close.", "TLS has already negotiated.", "SYN_SENT is early. Think filter, route, or the other side not listening. It is not an application bug yet."),
    q("net-tcp", "medium", "TIME_WAIT on the end that closed first is there to:", "Absorb delayed packets so they are not delivered to a new connection that reused the tuple.", "Hold the port forever. The only fix is a reboot.", "Mean the remote host crashed.", "Reserve memory for UDP.", "A pile of TIME_WAIT is often normal after many short connections. It is not, by itself, a leak."),
    q("net-tcp", "hard", "UDP 'worked in dev' and drops updates under load. Why is that unsurprising?", "UDP does not retransmit or keep order. The application has to notice loss.", "UDP has the same handshake and retry as TCP.", "The kernel always upgrades UDP to TCP when a packet is lost.", "UDP cannot be filtered.", "If the protocol needed reliability, it had to build it, or it should have been TCP."),
    q("net-tcp", "easy", "ss -ltn versus ss -lnt. What are you looking at with listening TCP sockets?", "Sockets in LISTEN, with addresses and ports, not the established client connections.", "Only UDP.", "The ARP cache.", "Firewall counters.", "A service that is not listening is not a DNS problem. Confirm the bind address, not just that the process exists."),
    q("net-http", "medium", "An ingress returns 503 and the pods are Running but not Ready. What does 503 mean here?", "The proxy has no usable upstream. Readiness removed the pods from the Service endpoints.", "The TLS certificate is expired. That is always 503.", "DNS for the cluster is down. 503 is the DNS code.", "The client sent a bad header. That is 503.", "503 from an ingress is often 'zero ready endpoints'. Fix readiness before you rewrite the Ingress."),
    q("net-http", "medium", "502 from a reverse proxy usually means:", "The proxy reached something, but the upstream response was invalid or the connection failed mid-attempt.", "The proxy has no configuration at all, which is 404.", "The client timed out before sending a byte. That is 499 only, and never 502.", "Authentication failed.", "502 is a bad gateway: the next hop misbehaved. 503 is 'I have nobody healthy to call'."),
    q("net-http", "easy", "What does a Host header let one IP do?", "Serve many sites. The name in Host, or SNI for HTTPS, picks the site.", "Encrypt the body.", "Replace DNS.", "Set the TCP window.", "Virtual hosting is the Host header. The IP alone is not the site."),
    q("net-http", "hard", "A health check uses HTTP and the app only speaks HTTP/2 cleartext on that port. The check fails. What is the mismatch?", "The checker spoke HTTP/1.1 and the server did not. The protocol on the health port has to be what the checker sends.", "HTTP/2 cannot listen on a port.", "Health checks are UDP.", "HTTP/2 disables status codes.", "Match the probe to the protocol the process actually speaks. A TCP probe would only prove the port accepts a handshake."),
    q("net-tls", "medium", "A client says certificate signed by unknown authority. The certificate is not expired. What is missing?", "The client does not trust the CA that signed the server certificate, or the chain was not sent.", "The server's private key is supposed to be installed on the client.", "TLS does not use CAs.", "The clock is irrelevant and so is the trust store.", "Trust is the CA bundle. Sending the leaf without intermediates, or using a private CA the client has never seen, produces this error."),
    q("net-tls", "medium", "You terminated TLS at the ingress and the app still redirects to https forever. What did the app fail to learn?", "That the original request was HTTPS. It only sees HTTP from the proxy unless you pass X-Forwarded-Proto or use a trusted header.", "That TLS 1.3 forbids redirects.", "That port 443 is UDP.", "The certificate's SAN. Redirects do not care about the scheme.", "The app's view of the scheme is the connection in front of it. Tell it the external scheme, and only trust that header from the proxy."),
    q("net-tls", "hard", "mTLS is required, and the server certificate verifies, but the connection still fails. What else has to be true?", "The client certificate has to be presented and accepted by the server's trust and policy.", "mTLS means the server skips certificate checks.", "Only the client needs a certificate. The server uses a password.", "mTLS is a DNS record.", "Both sides authenticate. A missing or untrusted client cert fails after the server cert succeeds."),
    q("net-tls", "easy", "Where does the server's private key belong?", "On the server, unreadable to everyone else. It is not sent during the handshake.", "In the certificate's SAN field.", "On every client.", "In DNS.", "The certificate is public. The key stays put. A key in git is a compromise, not a convenience."),
    q("net-tunnels", "medium", "You need the laptop to reach a database port that only the bastion can see. Which SSH form is that?", "Local forward, -L. The laptop listens, and the bastion connects onward.", "Remote forward, -R. That publishes your laptop on the bastion.", "-D is only a local forward of one port.", "ProxyJump cannot be combined with a forward.", "-L laptopPort:db:5432 jumps through the bastion. -R is the other direction.", IX, SSH),
    q("net-tunnels", "medium", "A developer must show a local port to the internet through a host they can SSH to. Which direction is the forward?", "Remote forward, -R. The remote host listens and sends the bytes back down the SSH connection.", "Local forward, -L.", "A SOCKS proxy on the remote host, which does not listen.", "SCP.", "-R is how a NATed laptop publishes a dev server. The listening socket is on the far side.", IX, SSH),
    q("net-tunnels", "hard", "kubectl must reach a private API server through a bastion, and you do not want a one-port -L. What does a SOCKS proxy plus the client give you?", "ssh -D makes a local SOCKS listener, and ALL_PROXY or the client's proxy setting sends the API calls through it.", "SOCKS replaces the kubeconfig.", "-D opens the API server to the internet.", "A SOCKS proxy only carries UDP.", "One SSH connection becomes a general TCP proxy for the tools that can use it, including kubectl.", IX, "https://labs.iximiuz.com/challenges/access-kubernetes-api-through-ssh-socks-proxy"),
    q("net-tunnels", "easy", "What is ProxyJump for, compared with -L?", "Getting an interactive or command SSH session onto the far host via a bastion. -L is for one TCP port.", "They are identical.", "ProxyJump forwards UDP only.", "ProxyJump copies the private key onto the bastion.", "Use -J when you want a shell or git over SSH. Use -L when you want a single TCP service."),
    q("net-firewall", "medium", "A security group and a subnet NACL both exist. The instance still cannot be reached. What is a property people forget about NACLs?", "NACLs are stateless. Return traffic needs its own allow. Security groups are stateful.", "NACLs are stateful and security groups are not.", "NACLs replace routes.", "Security groups can only allow, so they cannot be the problem. That part is true of the rule direction, but the NACL can still drop the return.", "An allow on inbound port 443 with a stateless NACL still needs the ephemeral return ports outbound, and the reverse on the way back."),
    q("net-firewall", "medium", "You want Node Exporter on the management NIC to be unreachable from the corporate NIC. The process already listens only on the management IP. What actually enforces the split?", "A filter on the ingress interface, or a per-service interface restriction. The listen address does not, on a weak end host.", "Binding to the management IP is sufficient on Linux.", "Deleting the default route.", "Moving the process to a different UID. UID selects the NIC.", "Match iif and the destination, or use RestrictNetworkInterfaces=. Do not expect bind() to be a firewall.", IX, DUAL),
    q("net-firewall", "hard", "Docker published a port and your careful INPUT drop never sees the packets. Where did they go?", "Docker puts forwarding and DNAT rules in its own chains. Traffic can be accepted in FORWARD or DOCKER-USER before your INPUT policy matters.", "Docker does not use iptables.", "Published ports are Unix sockets.", "INPUT is always the first hook for forwarded container traffic.", "The fix belongs in DOCKER-USER or the equivalent nft hook, not only in the host's INPUT chain."),
    q("net-firewall", "easy", "An allow rule that never matches is often explained by:", "The rule is after a final drop, or it matches the wrong interface, address, or connection state.", "Allow rules are ignored on Tuesdays.", "The kernel only reads the first rule in the table and skips the rest always.", "Ports above 1024 cannot be matched.", "Order and match criteria are the whole game. Read the counter. A counter that stays at zero is not the rule that is saving you."),
    q("net-nat", "medium", "A private subnet reaches the internet through a NAT gateway. What does the NAT change?", "The source address of outbound connections, so replies can come back to the gateway and be mapped to the instance.", "The destination of every inbound connection from the internet, automatically, to every instance.", "Nothing. NAT is a DNS feature.", "The MAC address only.", "Source NAT gives many private instances one public path out. It is not, by itself, an inbound allow."),
    q("net-nat", "medium", "Hairpin or NAT loopback pain shows up when:", "A client inside the NAT tries to reach the network's public address and the translation does not cover that path.", "Two public hosts ping each other.", "You add a default route.", "You use IPv6 only, which always hairpins.", "Internal clients often need the private address or split DNS. The public IP is the outside view."),
    q("net-nat", "hard", "SNAT and DNAT answer different questions. Which pairing is right?", "SNAT rewrites the source, typically for egress. DNAT rewrites the destination, typically to publish an internal service.", "Both rewrite the source.", "DNAT is only for ICMP.", "SNAT requires a load balancer and DNAT cannot be done in iptables.", "Docker's published ports are DNAT into the container. A NAT gateway is SNAT out."),
    q("net-nat", "easy", "Why can an instance in a private subnet download packages after you add a NAT gateway and a default route to it?", "Outbound connections are translated and the replies are mapped back. Inbound unsolicited connections are still not admitted.", "The NAT gateway gives the instance a public SSH listener.", "NAT disables the need for a route.", "The instance's private address becomes globally routable.", "Egress and ingress are different. Do not treat a working apt install as proof that the instance is exposed."),
    q("net-proxy", "medium", "A forward proxy and a reverse proxy sit on opposite sides of a connection. Which is which?", "A forward proxy acts for clients leaving a network. A reverse proxy acts for servers receiving traffic.", "They are two names for NAT.", "A reverse proxy is always a TCP dump.", "A forward proxy terminates the site's TLS certificate for the world.", "Egress filtering uses a forward proxy. An ingress, Nginx, or Envoy in front of an app is a reverse proxy."),
    q("net-proxy", "medium", "You put Nginx in front of an app and the app logs every request as coming from Nginx. What do you pass if you need the client?", "The real client address in a header such as X-Forwarded-For, and the app must trust it only from the proxy.", "Nothing. The TCP source is always the original client through a proxy.", "The server's private key.", "A DNS CNAME. That restores the address.", "The connection the app accepts is from the proxy. Headers restore the rest, and they are spoofable if you trust them from anywhere."),
    q("net-proxy", "hard", "An explicit forward proxy is set, and a program ignores it. What is a common reason?", "The program does not read http_proxy, or it was told to use a SOCKS proxy and the variable is an HTTP proxy.", "Proxies are applied by the kernel to every socket automatically.", "HTTPS cannot use a proxy.", "The variable only works for ping.", "Know which clients honor which variables. A Go binary, Java, and curl do not all behave the same."),
    q("net-proxy", "easy", "What is the job of a reverse proxy in front of several services on one host?", "It accepts the public connection and picks a backend from the name or the path.", "It replaces the need for IP addresses.", "It stores the git history.", "It is a packet capture.", "One listener, many apps. That is virtual hosting plus routing."),
    q("net-lb", "medium", "L4 and L7 load balancing differ because:", "L4 balances TCP or UDP connections without reading the HTTP. L7 can route on host, path, and headers.", "L7 cannot terminate TLS.", "L4 rewrites HTTP paths.", "They are the same once the packet is IP.", "Pick L4 when you want simplicity and preserved connections. Pick L7 when the URL decides the backend."),
    q("net-lb", "medium", "A balancer with no health check keeps sending users to a dead server. What does the check add?", "The balancer stops choosing targets that fail the check, so one bad instance is removed from rotation.", "It reboots the instance.", "It disables the need for readiness.", "It encrypts the backend.", "The check has to speak the protocol you care about. A TCP check stays green while the app returns 500."),
    q("net-lb", "hard", "Session affinity is on, and one backend is hot while others idle. Why can that happen?", "Affinity pins clients to one target. A few heavy clients, or a proxy that looks like one client, stick to one server.", "Affinity always spreads evenly.", "Load balancers ignore weights when affinity is on, and they send everything to the newest pod.", "Affinity is a DNS TTL.", "Affinity is a trade. A source-IP sticky rule behind one NAT sends an entire office to one pod."),
    q("net-lb", "easy", "What does a round-robin balancer ignore?", "The cost of each request. It counts connections or picks in turn, unless you configured a smarter policy.", "The list of targets.", "Health checks, if you configured them.", "New connections.", "Round robin is fair by count, not by CPU. A few expensive requests make it look unfair."),
    q("net-cloud", "medium", "A public subnet and a private subnet in the same VPC differ by:", "The route table. The public one has a route to the internet gateway. The private one does not.", "The fact that private subnets cannot run compute.", "The CIDR. Private subnets must be /32.", "DNS. Private subnets cannot resolve names.", "Public means routable to the IGW, not 'safe' or 'unsafe' by itself. The security group still matters."),
    q("net-cloud", "medium", "Instances in a private subnet need software updates. You do not want them to have public IPs. What is the usual egress path?", "A route to a NAT gateway in a public subnet.", "A second internet gateway directly on the private route table, which would make it public.", "Public IPs are required for any outbound packet.", "VPC peering to the internet.", "The NAT lives where the IGW is reachable. The instances keep private addresses."),
    q("net-cloud", "hard", "Two VPCs are peered. A ping works and the application still times out. What did peering not do?", "It did not open the security groups, the NACLs, or the target's listening port. Peering is a route.", "It automatically allows all ports both ways.", "It provides DNS for both VPCs with no extra setup in every design.", "It assigns public IPs.", "Add the route, then allow the actual port. People stop after the route and blame the peer."),
    q("net-cloud", "easy", "A VPN into a cloud VPC is for:", "Extending a private network so your side can reach private addresses, with crypto on the path.", "Publishing every instance to the internet.", "Replacing IAM.", "Disabling security groups.", "The VPN is a private path. It is not an authorization policy."),
    q("net-dual", "medium", "Node Exporter listens on 10.20.0.10:9100. A laptop on another NIC's subnet can still open it. What model allows that?", "The weak end host model. The kernel treats every local IP as local on every interface.", "The strong end host model, which accepts any local IP on any NIC. That description is the weak model.", "ARP proxy, which is required for this and cannot be disabled.", "Only if IP forwarding is off. Forwarding off prevents local delivery.", "Confirm with a capture on the unexpected NIC. Then filter that ingress, or constrain the service's interfaces.", IX, DUAL),
    q("net-dual", "hard", "You fixed the dual-homed leak with a firewall rule. What must the rule match to keep management working?", "Drop the exporter's port when it arrives on the corporate interface. Leave the same flow alone when it arrives on the management interface.", "Drop every packet to the host.", "Drop the management interface entirely.", "Allow the corporate interface to every port and drop management.", "Interface plus destination is the split. A blanket drop of the port removes the legitimate clients too.", IX, DUAL),
    q("net-dual", "medium", "Changing the listen address did not close the unexpected path. Why does the lesson say that?", "The packet is delivered locally before the listen address can express 'only from this NIC'.", "ss cannot show a listen address.", "Linux ignores bind().", "The application rewrites its own listen address every minute.", "Check ss to prove the bind, then filter the interface anyway.", IX, DUAL),
    q("net-dual", "easy", "A dual-homed server has a corporate NIC and a management NIC. Where should administration run?", "On the management network, with the corporate NIC unable to reach those ports.", "On every interface, so you have a backup.", "Only on the public internet.", "On a random high port with no filter, because high ports are safe.", "Management on the data NIC is how a network incident becomes a host incident."),
    q("net-l2", "medium", "In the data center tour, a top-of-rack switch in front of one rack behaves as:", "A bridge for the servers in the rack, and a router on the uplink toward the distribution layer.", "A pure router with no L2 at all.", "A hub that floods every frame out every port including the ones it has learned.", "A TLS terminator.", "Same hardware can bridge some ports and route others. The rack is one L2 segment. The uplink is L3.", IX, BRIDGE),
    q("net-l2", "medium", "Why is the out-of-band port on a switch not just another bridged port?", "It stays a routed management interface so a bad bridge or ACL cannot lock you out of the device.", "It only carries broadcasts.", "It is electrically the same as disabling SSH.", "It is required to be in the same VLAN as the servers or management does not work.", "Configure the device on a path that does not depend on the forwarding plane you are editing.", IX, BRIDGE),
    q("net-l2", "hard", "You want one broadcast domain across racks that are already separate L3 networks. What overlay did the course point at?", "VXLAN. It carries the L2 frame over the L3 underlay.", "A larger subnet mask on the physical NICs only. That does not cross a router.", "NAT.", "HTTP.", "The physical network stays L3 between racks. The overlay paints the broadcast domain the workload wanted.", IX, BRIDGE),
    q("net-l2", "easy", "A Linux bridge in a container host is playing which role?", "The same logical bridge a switch plays: it forwards frames between the container veths and the uplink.", "A router only.", "A userspace TCP proxy.", "A DNS server.", "docker0 and friends are bridges. The containers are just ports.", IX, BRIDGE),
]
